-- Table structure for `attendance`
-- ----------------------------
DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `attendance_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `position` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `department_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `department_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Unassigned',
  `attendance_date` date NOT NULL,
  `clock_in` time DEFAULT NULL,
  `clock_out` time DEFAULT NULL,
  `clock_in_photo` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `clock_in_latitude` decimal(10,7) DEFAULT NULL,
  `clock_in_longitude` decimal(10,7) DEFAULT NULL,
  `clock_in_accuracy_m` decimal(10,2) DEFAULT NULL,
  `status` enum('Complete','Incomplete') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Incomplete',
  `late` tinyint(1) NOT NULL DEFAULT '0',
  `late_minutes` int unsigned NOT NULL DEFAULT '0',
  `early_out` tinyint(1) NOT NULL DEFAULT '0',
  `early_out_minutes` int unsigned NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`attendance_id`),
  UNIQUE KEY `uq_attendance_employee_date` (`employee_number`,`attendance_date`),
  KEY `idx_attendance_date` (`attendance_date`),
  CONSTRAINT `fk_attendance_employee` FOREIGN KEY (`employee_number`) REFERENCES `employees` (`employee_number`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14915 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

