-- Table structure for `excuses`
-- ----------------------------
DROP TABLE IF EXISTS `excuses`;
CREATE TABLE `excuses` (
  `excuse_id` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_number` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `employee_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `position` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `department_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `department_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `absence_start` date NOT NULL,
  `absence_end` date NOT NULL,
  `absence_time` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `reason` enum('Medical Appointment','Illness','Family Emergency','Official Assignment','Other') COLLATE utf8mb4_unicode_ci NOT NULL,
  `other_reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `supporting_documents` json DEFAULT NULL,
  `supervisor_name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `supervisor_decision` enum('Approved','Not Approved') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `supervisor_comments` text COLLATE utf8mb4_unicode_ci,
  `hr_reviewed_by` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `hr_approved` enum('Yes','No') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `reviewed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`excuse_id`),
  KEY `idx_excuses_dates` (`absence_start`,`absence_end`),
  KEY `idx_excuses_employee` (`employee_number`),
  CONSTRAINT `fk_excuses_employee` FOREIGN KEY (`employee_number`) REFERENCES `employees` (`employee_number`) ON DELETE CASCADE,
  CONSTRAINT `chk_excuse_dates` CHECK ((`absence_end` >= `absence_start`))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

